pub fn new(data: T) -> Box<T> {
        let layout = Layout::new::<T>();
        unsafe {
            let mut p = NonNull::new(default_allocator().alloc(layout) as *mut T).unwrap();
            *(p.as_mut()) = data;
            Self { data: p }
        }
    }

